/**
 * Panel of display preferences (button « Aa », shortcut Alt+A).
 *
 * Each change is applied at once, as classes on the html element, and saved in the profile of
 * the user, so that it holds on every page and every device.
 *
 * @module     theme_epure/a11y_panel
 * @copyright  2026 Eric Falcon
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import Ajax from 'core/ajax';
import {getString} from 'core/str';
import * as Guide from 'theme_epure/reading_guide';
import * as ReadAloud from 'theme_epure/read_aloud';

/** Preferences that are on or off. */
const SWITCHES = ['spacing', 'lines', 'contrast', 'underline', 'motion', 'stillimages', 'scrollbars', 'speech'];

/**
 * Current choices of the panel.
 *
 * @param {HTMLElement} panel The panel.
 * @returns {{text: number, font: string, switches: Object<string, boolean>}}
 */
const read = (panel) => ({
    text: Number(panel.querySelector('[name="epure-a11y-text"]:checked')?.value || 100),
    font: panel.querySelector('[name="epure-a11y-font"]:checked')?.value || '',
    scheme: panel.querySelector('[name="epure-a11y-scheme"]:checked')?.value || '',
    guide: panel.querySelector('[name="epure-a11y-guide"]:checked')?.value || '',
    switches: Object.fromEntries(SWITCHES.map((name) => [name, !!panel.querySelector(`[name="epure-a11y-${name}"]`)?.checked])),
});

/**
 * Applies the choices to the page.
 *
 * @param {{text: number, font: string, scheme: string, switches: Object<string, boolean>}} choices Choices.
 * @param {string} defaultScheme Scheme of the site or the company: light, dark or auto.
 */
const applyToPage = (choices, defaultScheme) => {
    const html = document.documentElement;
    [...html.classList].filter((name) => name.startsWith('epure-a11y-') || name.startsWith('epure-dark'))
        .forEach((name) => html.classList.remove(name));
    const scheme = choices.scheme || defaultScheme;
    if (scheme === 'dark' || scheme === 'yellow') {
        html.classList.add('epure-dark');
    } else if (scheme === 'auto') {
        html.classList.add('epure-dark-auto');
    }
    if (scheme === 'yellow' || scheme === 'cream') {
        html.classList.add(`epure-a11y-scheme-${scheme}`);
    }
    if (choices.guide) {
        html.classList.add(`epure-a11y-guide-${choices.guide}`);
    }
    Guide.set(choices.guide);
    ReadAloud.set(choices.switches.speech);
    if (choices.text !== 100) {
        html.classList.add(`epure-a11y-text-${choices.text}`);
    }
    if (choices.font) {
        html.classList.add(`epure-a11y-font-${choices.font}`);
    }
    SWITCHES.filter((name) => choices.switches[name]).forEach((name) => html.classList.add(`epure-a11y-${name}`));
    // The primary navigation moves the items that no longer fit into its « More » menu on resize.
    window.dispatchEvent(new Event('resize'));
};

/**
 * Saves the choices in the profile of the user, or in the cookie of a visitor, and says whether it was saved.
 *
 * @param {HTMLElement} panel The panel.
 * @param {{text: number, font: string, switches: Object<string, boolean>}} choices Choices.
 * @return {Promise<boolean>} Whether the choices are saved.
 */
const save = async(panel, choices) => {
    const preferences = [
        {type: 'theme_epure_a11y_text', value: String(choices.text)},
        {type: 'theme_epure_a11y_font', value: choices.font},
        {type: 'theme_epure_a11y_scheme', value: choices.scheme},
        {type: 'theme_epure_a11y_guide', value: choices.guide},
        ...SWITCHES.map((name) => ({type: `theme_epure_a11y_${name}`, value: choices.switches[name] ? '1' : '0'})),
    ];
    const status = panel.querySelector('[data-region="status"]');
    const cookie = panel.closest('[data-region="epure-a11y"]').dataset.cookie;
    try {
        if (cookie) {
            // A visitor: in a cookie of the browser, read by the server for the next pages, kept a year.
            const values = Object.fromEntries(preferences.map(({type, value}) => [type.replace('theme_epure_a11y_', ''), value]));
            const secure = window.location.protocol === 'https:' ? '; Secure' : '';
            const value = encodeURIComponent(JSON.stringify(values));
            document.cookie = `${cookie}=${value}; path=/; max-age=31536000; SameSite=Lax${secure}`;
            // A browser that refuses the cookies keeps nothing: read back.
            if (!document.cookie.split('; ').includes(`${cookie}=${value}`)) {
                throw new Error('cookie refused');
            }
            status.textContent = await getString('a11ysaved_visitor', 'theme_epure');
            return true;
        }
        await Ajax.call([{methodname: 'core_user_update_user_preferences', args: {preferences}}])[0];
        status.textContent = await getString('a11ysaved', 'theme_epure');
        return true;
    } catch (error) {
        status.textContent = await getString('a11ynotsaved', 'theme_epure');
        return false;
    }
};

/**
 * Saves the choices one request at a time: changed quickly, they would otherwise be saved in parallel, and an
 * earlier state that is saved last would replace the last choice.
 *
 * @param {HTMLElement} panel The panel.
 * @return {function(Object): Promise<boolean>} Saves the choices once the previous save has ended; only the last waits.
 *     Its promise says whether the last choices were saved.
 */
const saver = (panel) => {
    let running = null;
    let waiting = null;
    return (choices) => {
        waiting = choices;
        if (!running) {
            running = (async() => {
                let saved = true;
                while (waiting) {
                    const next = waiting;
                    waiting = null;
                    saved = await save(panel, next);
                }
                running = null;
                return saved;
            })();
        }
        return running;
    };
};

/**
 * Whether the user is typing: in a field, a list or an editor, the keys are theirs.
 *
 * @param {EventTarget} target The target of the key.
 * @return {boolean}
 */
const typing = (target) => target instanceof HTMLElement
    && (target.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName))
    && !(target.tagName === 'INPUT' && ['checkbox', 'radio', 'button', 'submit'].includes(target.type));

/**
 * Starts the panel.
 */
export const init = () => {
    const region = document.querySelector('[data-region="epure-a11y"]');
    // The header may be rendered more than once: the panel is only started once.
    if (!region || region.dataset.initialised) {
        return;
    }
    region.dataset.initialised = '1';
    const toggle = region.querySelector('[data-action="toggle"]');
    const panel = region.querySelector('.epure-a11y-panel');
    const defaultScheme = region.dataset.defaultScheme || 'light';

    const open = () => {
        panel.hidden = false;
        toggle.setAttribute('aria-expanded', 'true');
        // After the click has ended: Moodle's own handlers of header buttons give them the focus back.
        setTimeout(() => (panel.querySelector('input:checked') || panel.querySelector('input')).focus(), 0);
    };
    const close = (restoreFocus = true) => {
        if (panel.hidden) {
            return;
        }
        panel.hidden = true;
        toggle.setAttribute('aria-expanded', 'false');
        if (restoreFocus) {
            toggle.focus();
        }
    };

    toggle.addEventListener('click', () => (panel.hidden ? open() : close()));
    region.querySelector('[data-action="close"]').addEventListener('click', () => close());
    panel.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            e.preventDefault();
            close();
        }
    });
    document.addEventListener('click', (e) => {
        if (!region.contains(e.target)) {
            close(false);
        }
    });
    // Alt + A, except while typing: on a Mac, Option + A writes « å ».
    document.addEventListener('keydown', (e) => {
        if (e.altKey && !e.ctrlKey && !e.metaKey && !typing(e.target)
                && (e.key === 'a' || e.key === 'A' || e.code === 'KeyA')) {
            e.preventDefault();
            if (panel.hidden) {
                open();
            } else {
                close();
            }
        }
    });

    const queue = saver(panel);
    const changed = () => {
        const choices = read(panel);
        applyToPage(choices, defaultScheme);
        return queue(choices);
    };
    panel.addEventListener('change', changed);
    // A preference set from a profile or the reset, as the user would tick it.
    const check = (name, value) => {
        const input = panel.querySelector(`[name="epure-a11y-${name}"][value="${value}"]`);
        if (input) {
            input.checked = true;
        }
    };
    // The reading aloud is kept by a profile, as the colours.
    const defaults = (keep = []) => {
        check('text', 100);
        check('font', '');
        check('guide', '');
        SWITCHES.filter((name) => !keep.includes(name)).forEach((name) => {
            const input = panel.querySelector(`[name="epure-a11y-${name}"]`);
            if (input) {
                input.checked = false;
            }
        });
    };
    region.querySelector('[data-action="reset"]').addEventListener('click', () => {
        defaults();
        check('scheme', '');
        changed();
    });
    // A profile replaces the preferences: what it does not set goes back to its default, the colours kept.
    panel.querySelectorAll('[data-action="profile"]').forEach((button) => button.addEventListener('click', async() => {
        const profile = JSON.parse(button.dataset.choices);
        defaults(['speech']);
        check('text', profile.text);
        check('font', profile.font);
        check('guide', profile.guide);
        profile.switches.forEach((name) => {
            panel.querySelector(`[name="epure-a11y-${name}"]`).checked = true;
        });
        // Applied to the page in any case; said applied only once saved, else that it will be lost.
        const saved = await changed();
        panel.querySelector('[data-region="status"]').textContent = await getString(
            saved ? 'a11yprofile_applied' : 'a11yprofile_notsaved',
            'theme_epure',
            button.textContent.trim()
        );
    }));
    Guide.init();
    ReadAloud.init();
    // Without voices of the device, no reading aloud to offer: the voices of a service on the network are not used.
    ReadAloud.available().then((available) => {
        if (!available) {
            panel.querySelector('[name="epure-a11y-speech"]')?.closest('.epure-a11y-switch')?.remove();
        }
        return available;
    }).catch(() => null);
};
